using System;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.IO;using System.IO.Compression;using System.Reflection;using System.Runtime.CompilerServices;using System.Security.Cryptography;using System.Text;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;using Microsoft.Web.WebView2.Core;using Microsoft.Web.WebView2.WinForms;
namespace ZiXing {
 static class Program {
  [STAThread]static void Main(string[] args){try{
   if(args.Length!=4||args[0]!="--parent"||args[2]!="--host")throw new Exception("请从 Illustrator 的“窗口 → 字醒”打开插件。");
   int parent=int.Parse(args[1]);var process=Process.GetProcessById(parent);string expected=Path.GetFullPath(args[3]);if(!string.Equals(process.MainModule.FileName,expected,StringComparison.OrdinalIgnoreCase)||!Path.GetFileName(expected).Equals("Illustrator.exe",StringComparison.OrdinalIgnoreCase))throw new Exception("Illustrator 启动信息无效。");
   using(var mutex=new Mutex(true,"Local\\ZiXingPanel-"+parent,out bool created)){if(!created)return;
    string resources=Extract();AppDomain.CurrentDomain.AssemblyResolve+=(sender,eventArgs)=>{string name=new AssemblyName(eventArgs.Name).Name;if(name=="Microsoft.Web.WebView2.Core"||name=="Microsoft.Web.WebView2.WinForms")return Assembly.LoadFrom(Path.Combine(resources,name+".dll"));return null;};Run(resources,expected,parent);
   }
  }catch(Exception ex){MessageBox.Show(ex.Message,"字醒",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
  static string Extract(){string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"assets");Directory.CreateDirectory(root);using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("ZiXing.Payload"))using(var archive=new ZipArchive(stream,ZipArchiveMode.Read))foreach(var entry in archive.Entries){string dest=Path.GetFullPath(Path.Combine(root,entry.FullName));if(!dest.StartsWith(Path.GetFullPath(root)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("插件包路径无效。");Directory.CreateDirectory(Path.GetDirectoryName(dest));using(var input=entry.Open())using(var output=File.Create(dest))input.CopyTo(output);}return root;}
  [MethodImpl(MethodImplOptions.NoInlining)]static void Run(string resources,string host,int parent){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new Panel(resources,host,parent));}
 }
 sealed class Panel:Form {
  readonly string resources;readonly int parent;readonly HostBridge host;readonly FontMatcher matcher=new FontMatcher();readonly WebView2 web=new WebView2();string work;bool busy,closing;readonly System.Windows.Forms.Timer lifetime=new System.Windows.Forms.Timer{Interval=1500};
  public Panel(string resources,string hostPath,int parentPid){this.resources=resources;parent=parentPid;host=new HostBridge(resources,hostPath,parent);Text="字醒 · Windows 测试版";ClientSize=new Size(400,720);MinimumSize=new Size(360,500);StartPosition=FormStartPosition.CenterScreen;ShowInTaskbar=true;web.Dock=DockStyle.Fill;Controls.Add(web);Shown+=async(s,e)=>{try{await Initialize();}catch(Exception ex){MessageBox.Show("面板无法启动："+ex.Message+"\n请安装 Microsoft Edge WebView2 Runtime。","字醒");Close();}};lifetime.Tick+=(s,e)=>{try{if(Process.GetProcessById(parent).HasExited)Close();}catch(ArgumentException){Close();}};lifetime.Start();FormClosed+=(s,e)=>{closing=true;lifetime.Stop();web.Dispose();if(!busy)Clean();};}
  async Task Initialize(){CoreWebView2Environment.SetLoaderDllFolderPath(resources);string userData=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ZiXing","WebView2",parent.ToString());var env=await CoreWebView2Environment.CreateAsync(null,userData);await web.EnsureCoreWebView2Async(env);web.CoreWebView2.SetVirtualHostNameToFolderMapping("zixing.local",Path.Combine(resources,"web"),CoreWebView2HostResourceAccessKind.DenyCors);web.CoreWebView2.Settings.AreDevToolsEnabled=false;web.CoreWebView2.Settings.IsStatusBarEnabled=false;web.CoreWebView2.Settings.AreDefaultContextMenusEnabled=false;
   web.CoreWebView2.NavigationStarting+=(s,e)=>{Uri uri;if(!Uri.TryCreate(e.Uri,UriKind.Absolute,out uri)||uri.Scheme!="https"||uri.Host!="zixing.local")e.Cancel=true;};web.CoreWebView2.NewWindowRequested+=(s,e)=>e.Handled=true;web.CoreWebView2.PermissionRequested+=(s,e)=>e.State=CoreWebView2PermissionState.Deny;
   web.CoreWebView2.AddWebResourceRequestedFilter("*",CoreWebView2WebResourceContext.All);web.CoreWebView2.WebResourceRequested+=(s,e)=>{Uri uri;if(Uri.TryCreate(e.Request.Uri,UriKind.Absolute,out uri)&&uri.Scheme=="https"&&uri.Host=="zixing.local")return;if(e.Request.Uri.StartsWith("data:")||e.Request.Uri.StartsWith("blob:https://zixing.local/"))return;e.Response=env.CreateWebResourceResponse(new MemoryStream(),403,"Blocked","");};
   web.CoreWebView2.WebMessageReceived+=async(s,e)=>{if(!e.Source.StartsWith("https://zixing.local/",StringComparison.Ordinal))return;await Receive(e.WebMessageAsJson);};web.CoreWebView2.Navigate("https://zixing.local/index.html");}
  void Clean(){if(work==null)return;try{Directory.Delete(work,true);}catch(IOException){}catch(UnauthorizedAccessException){}work=null;}
  void Deliver(object value){if(closing||IsDisposed)return;string json=Json.Encode(value);string encoded=Convert.ToBase64String(Encoding.UTF8.GetBytes(json));BeginInvoke((Action)(()=>{if(!closing)web.CoreWebView2.ExecuteScriptAsync("window.__zixingDeliver('"+encoded+"')");}));}
  async Task Receive(string raw){string id=null;bool ownsBusy=false;try{var request=Json.Object(raw);id=Json.String(request,"id");string method=Json.String(request,"method");object p;if(id==null||!request.TryGetValue("payload",out p)||!(p is Dictionary<string,object>))return;var payload=(Dictionary<string,object>)p;if(busy)throw new Exception("请等待当前操作完成。");busy=true;ownsBusy=true;object result;
   if(method=="cleanup"){Clean();result=new object();}
   else if(method=="host"){string action=Json.String(payload,"action");if(Array.IndexOf(new[]{"ping","fonts","capture","rebuild","mergeText"},action)<0)throw new Exception("文档操作无效。");object arg;if(!payload.TryGetValue("payload",out arg)||!(arg is Dictionary<string,object>))throw new Exception("操作参数无效。");var args=(Dictionary<string,object>)arg;if(action=="capture"){Clean();work=Path.Combine(Path.GetTempPath(),"zixing-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(work);args["path"]=Path.Combine(work,"selection.png");}result=await host.Execute(action,args);if(action=="capture"||action=="rebuild"||action=="mergeText")Activate();}
   else if(method=="image"){if(work==null)throw new Exception("识别记录已失效。");byte[] bytes=File.ReadAllBytes(Path.Combine(work,"selection.png"));if(bytes.Length>48*1024*1024)throw new Exception("选区图片过大。");result=new{image="data:image/png;base64,"+Convert.ToBase64String(bytes)};}
   else if(method=="match"){if(work==null)throw new Exception("识别记录已失效。");string image=Path.Combine(work,"selection.png");result=await Task.Run(()=>matcher.Match(image,payload,value=>Deliver(new{id,eventType="progress",data=value})));}
   else throw new Exception("不支持的原生操作。");Deliver(new{id,ok=true,data=result});
  }catch(Exception ex){if(id!=null)Deliver(new{id,ok=false,error=ex.Message});}finally{if(ownsBusy)busy=false;if(closing)Clean();}}
 }
}
